#!/usr/bin/env bash
set -eo pipefail
export HOME=/root
export PATH="$HOME/.local/bin:$PATH"
cd /opt/mesocyclonic-viewer
echo '' | base64 -d > 'scripts/model/resumen_pitch.py'
uv run python scripts/model/resumen_pitch.py 2>&1 | tail -3
echo "=== resumen_pitch.md ==="
base64 -w0 data/outputs/resumen_pitch.md
echo ""; echo DONE
